namespace LSE.AutoCADElectrical.Librarian;
public static class LibraryTransactionService{
 public static LibraryResult Execute(AppSettings s,LibraryStandard std,LibraryRequest q,Action<string>? progress=null){
  Validate(s,std,q);var r=std.Rule(q.Kind);string menuPath=s.MenuPathFor(r);
  var writeTargets=new List<string>{menuPath};if(q.RegisterLookup)writeTargets.Add(s.FootprintLookupPath);if(q.AddCatalogRecord)writeTargets.Add(s.CatalogPath);if(q.InPlace)writeTargets.Add(q.TargetPath);VaultProbe.RequireWritable(writeTargets);
  string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");string backup=Path.Combine(s.BackupFolder,stamp);Directory.CreateDirectory(backup);
  var log=new List<string>{$"Started: {DateTime.Now:s} by {Environment.UserName}@{Environment.MachineName}",$"Kind: {r.DisplayName}",$"Source: {(q.FromCurrentDrawing?"block "+q.SourceBlockName+" in the current drawing":q.SourcePath)}",$"Target: {q.TargetPath}",$"Icon menu: {menuPath}",$"Backup folder: {backup}"};void Log(string m){log.Add(m);progress?.Invoke(m);}foreach(string m in log)progress?.Invoke(m);
  string menuBackup=Path.Combine(backup,Path.GetFileName(menuPath));string? lookupBackup=q.RegisterLookup?Path.Combine(backup,Path.GetFileName(s.FootprintLookupPath)):null;
  using var gate=LibraryLock.Acquire(s.IconMenuFolder,log);File.Copy(menuPath,menuBackup,true);if(lookupBackup is not null)File.Copy(s.FootprintLookupPath,lookupBackup,true);Log("Backups: PASS");
  bool createdFolder=false,createdDrawing=false,createdImage=false,menuWritten=false,lookupWritten=false;string imagePath="";var result=new LibraryResult{Request=q,MenuPath=menuPath};
  try{
   if(!Directory.Exists(q.TargetFolder)){Directory.CreateDirectory(q.TargetFolder);createdFolder=true;Log("Created folder "+q.TargetFolder);}
   if(q.InPlace)Log("Drawing is already in the library at the target path: PASS (not copied)");
   else if(q.FromCurrentDrawing){DrawingInspectionService.ExportBlock(q.SourceBlockName,q.TargetPath);createdDrawing=true;Log($"Block {q.SourceBlockName} exported from the current drawing (WBLOCK): PASS");}else{File.Copy(q.SourcePath,q.TargetPath,false);createdDrawing=true;File.SetAttributes(q.TargetPath,FileAttributes.Normal);Log("Drawing copied into the library: PASS");}
   if(!File.Exists(q.TargetPath))throw new InvalidOperationException("The library drawing was not created: "+q.TargetPath);result.DrawingPath=q.TargetPath;
   string imageField="";
   if(q.Icon==IconSource.None)Log("Icon: none (the icon menu entry will show no picture)");
   else if(q.Icon==IconSource.ExistingImage){imageField=std.ImagePrefix+Path.GetFileName(q.IconPath);result.ImagePath=q.IconPath;Log("Icon: existing image "+q.IconPath);}
   else{imagePath=Path.Combine(s.ImagesFolder,q.Name+".png");Directory.CreateDirectory(s.ImagesFolder);IconRenderService.WriteIcon(q.Icon,q.TargetPath,q.IconPath,imagePath,s.IconPixels);createdImage=true;imageField=std.ImagePrefix+Path.GetFileName(imagePath);result.ImagePath=imagePath;Log($"Icon ({q.Icon}) written: {imagePath} ({s.IconPixels} px)");}
   var menu=IconMenuService.Load(menuPath);IconMenuPage page;
   if(q.CreatePage){var parent=menu.Page(q.ParentPage)??throw new InvalidOperationException("Parent page "+q.ParentPage+" was not found in "+menuPath);page=IconMenuService.AddPage(menu,q.NewPageTitle,parent,q.NewPageTitle,imageField);Log($"Icon menu page {page.Id} \"{page.Title}\" created under {parent.Id} ({parent.Title})");}
   else page=menu.Page(q.MenuPage)??throw new InvalidOperationException("Page "+q.MenuPage+" was not found in "+menuPath);
   string action=r.ActionTemplate.Replace("{PATH}",q.TargetPath,StringComparison.OrdinalIgnoreCase);IconMenuService.AddEntry(menu,page,q.MenuLabel,imageField,action);
   var check=IconMenuService.Parse(IconMenuService.Render(menu));if(!(check.Page(page.Id)?.Entries.Any(e=>e.IsEntry&&e.Action.Equals(action,StringComparison.OrdinalIgnoreCase)&&e.Label.Equals(q.MenuLabel.Trim(),StringComparison.OrdinalIgnoreCase))??false))throw new InvalidOperationException("The new entry did not survive a re-parse of the rendered icon menu; the menu file was not written.");
   IconMenuService.Save(menu);menuWritten=true;result.MenuPage=page.Id;Log($"Icon menu entry added to {Path.GetFileName(menuPath)} page {page.Id} ({page.Title}): {q.MenuLabel}|{imageField}|{action}");
   if(q.RegisterLookup){var fp=new FootprintLookupService(s.FootprintLookupPath);fp.EnsureTable(q.LookupManufacturer);fp.Upsert(q.LookupManufacturer,q.LookupCatalog,q.TargetPath,q.Description);lookupWritten=true;if(fp.Find(q.LookupManufacturer,q.LookupCatalog) is null)throw new InvalidOperationException("Read-back of the footprint lookup row failed.");Log($"Footprint lookup [{q.LookupManufacturer}] {q.LookupCatalog} -> {q.TargetPath}: PASS");}
   else if(q.Kind is LibraryKind.PanelFootprint or LibraryKind.Nameplate)Log("Footprint lookup: SKIPPED (not requested). AutoCAD Electrical will still insert the footprint from the icon menu; catalog-driven insertion needs a footprint_lookup.mdb row.");
   if(q.AddCatalogRecord){var naming=NamingWorkbookService.Load(s);Log("Catalog record: "+q.CatalogRecord!.Summary+" (naming standard from "+(naming.FromWorkbook?"workbook ":"JSON snapshot ")+naming.Source+")");var cr=CatalogTransactionService.Run(s,naming,q.PartNumber!,q.CatalogRecord,Log);result.PartNumber=cr.PartNumber;Log($"Catalog record added with LSE part number {cr.PartNumber} (catalog backup in {cr.BackupFolder})");}
   Log("Status: SUCCESS");
   var touched=new List<string>();if(menuWritten)touched.Add(menuPath);if(createdDrawing||q.InPlace)touched.Add(q.TargetPath);if(createdImage)touched.Add(imagePath);if(lookupWritten)touched.Add(s.FootprintLookupPath);if(q.AddCatalogRecord)touched.Add(s.CatalogPath);foreach(string m in VaultProbe.CheckinReminder(touched))Log(m);
   File.WriteAllLines(Path.Combine(backup,"LibraryReport.txt"),log);
   s.RecentItems.RemoveAll(x=>x.Equals(q.TargetPath,StringComparison.OrdinalIgnoreCase));s.RecentItems.Insert(0,q.TargetPath);if(s.RecentItems.Count>25)s.RecentItems.RemoveRange(25,s.RecentItems.Count-25);SettingsService.Save(s);
   result.Report=string.Join(Environment.NewLine,log);return result;}
  catch(Exception ex){Log("ERROR: "+ex.Message);
   if(menuWritten)try{File.Copy(menuBackup,menuPath,true);Log("Icon menu rollback: PASS");}catch(Exception rx){Log("Icon menu rollback: FAILED "+rx.Message);}
   if(lookupWritten&&lookupBackup is not null)try{File.Copy(lookupBackup,s.FootprintLookupPath,true);Log("Footprint lookup rollback: PASS");}catch(Exception rx){Log("Footprint lookup rollback: FAILED "+rx.Message);}
   if(createdImage)try{if(File.Exists(imagePath)){File.Delete(imagePath);Log("Rollback removed "+imagePath);}}catch(Exception rx){Log("Rollback could not remove "+imagePath+": "+rx.Message);}
   if(createdDrawing)try{if(File.Exists(q.TargetPath)){File.Delete(q.TargetPath);Log("Rollback removed "+q.TargetPath);}}catch(Exception rx){Log("Rollback could not remove "+q.TargetPath+": "+rx.Message);}
   if(createdFolder)try{if(!Directory.EnumerateFileSystemEntries(q.TargetFolder).Any()){Directory.Delete(q.TargetFolder);Log("Rollback removed folder "+q.TargetFolder);}}catch(Exception rx){Log("Rollback could not remove folder: "+rx.Message);}
   try{File.WriteAllLines(Path.Combine(backup,"LibraryReport.txt"),log.Append("Detail: "+ex));}catch{}
   throw new InvalidOperationException(string.Join(Environment.NewLine,log),ex);}
 }
 public static void Validate(AppSettings s,LibraryStandard std,LibraryRequest q){
  var r=std.Rule(q.Kind);var problems=NamingService.Validate(r,q.Name);if(problems.Count>0)throw new InvalidOperationException(string.Join(Environment.NewLine,problems));
  string root=s.RootFor(q.Kind);if(root.Trim().Length==0)throw new InvalidOperationException("The library folder for "+r.DisplayName.ToLowerInvariant()+" is not set (LSELIBRARYSETTINGS).");if(!Directory.Exists(root))throw new DirectoryNotFoundException("Library folder was not found: "+root);
  if(q.TargetFolder.Trim().Length==0||!(SameFolder(q.TargetFolder,root)||NamingService.Inside(Path.Combine(q.TargetFolder,"x"),root)))throw new InvalidOperationException("The target folder must be the "+r.DisplayName.ToLowerInvariant()+" library or a folder inside it: "+root);
  if(q.FromCurrentDrawing){if(q.SourceBlockName.Trim().Length==0)throw new InvalidOperationException("Choose the block in the current drawing to export.");}
  else{if(!File.Exists(q.SourcePath))throw new FileNotFoundException("Source drawing was not found.",q.SourcePath);if(!q.SourcePath.EndsWith(".dwg",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("The source must be a .dwg file.");}
  if(File.Exists(q.TargetPath)&&!q.InPlace)throw new InvalidOperationException("A library drawing with that name already exists: "+q.TargetPath);
  string? clash=FindByName(root,q.Name+".dwg",std);if(clash is not null&&!(q.InPlace&&Path.GetFullPath(clash).Equals(Path.GetFullPath(q.TargetPath),StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException("The name is already used elsewhere in the library (AutoCAD Electrical resolves blocks by name, so every name must be unique): "+clash);
  if(q.Kind==LibraryKind.SchematicSymbol&&s.StockSymbolLibraryFolder.Length>0&&Directory.Exists(s.StockSymbolLibraryFolder)){clash=FindByName(s.StockSymbolLibraryFolder,q.Name+".dwg",std);if(clash is not null)throw new InvalidOperationException("The name clashes with a stock AutoCAD Electrical symbol: "+clash);}
  string menuPath=s.MenuPathFor(r);if(!File.Exists(menuPath))throw new FileNotFoundException("Icon menu file was not found.",menuPath);var menu=IconMenuService.Load(menuPath);
  if(q.MenuLabel.Trim().Length==0)throw new InvalidOperationException("Icon menu label is required.");if(q.MenuLabel.Contains('|'))throw new InvalidOperationException("Icon menu label cannot contain '|'.");
  if(q.CreatePage){if(q.NewPageTitle.Trim().Length==0)throw new InvalidOperationException("Give the new icon menu page a title.");var parent=menu.Page(q.ParentPage)??throw new InvalidOperationException("Parent page "+q.ParentPage+" does not exist in "+Path.GetFileName(menuPath)+".");if(IconMenuService.HasLabel(parent,q.NewPageTitle))throw new InvalidOperationException($"Page {parent.Id} already has an entry labelled \"{q.NewPageTitle}\".");}
  else{var page=menu.Page(q.MenuPage)??throw new InvalidOperationException("Icon menu page "+q.MenuPage+" does not exist in "+Path.GetFileName(menuPath)+".");if(IconMenuService.HasLabel(page,q.MenuLabel))throw new InvalidOperationException($"Page {page.Id} ({page.Title}) already has an entry labelled \"{q.MenuLabel}\".");}
  if(s.IconMenuFolder.Trim().Length==0||!Directory.Exists(s.IconMenuFolder))throw new DirectoryNotFoundException("Icon menu folder was not found: "+s.IconMenuFolder);
  switch(q.Icon){case IconSource.ExistingImage:if(!File.Exists(q.IconPath))throw new FileNotFoundException("The chosen icon image was not found.",q.IconPath);if(!NamingService.Inside(q.IconPath,s.ImagesFolder))throw new InvalidOperationException("Existing icon images must live in the images folder: "+s.ImagesFolder);break;
   case IconSource.ImageFile:if(!File.Exists(q.IconPath))throw new FileNotFoundException("The image file to import was not found.",q.IconPath);break;case IconSource.None:break;default:break;}
  if(q.Icon is IconSource.Render or IconSource.Thumbnail or IconSource.ImageFile){string img=Path.Combine(s.ImagesFolder,q.Name+".png");if(File.Exists(img))throw new InvalidOperationException("An icon image with that name already exists: "+img+". Choose 'Reuse an existing image' or rename the item.");}
  if(q.RegisterLookup){if(q.Kind is not(LibraryKind.PanelFootprint or LibraryKind.Nameplate))throw new InvalidOperationException("Only footprints and nameplates are registered in footprint_lookup.mdb.");if(!File.Exists(s.FootprintLookupPath))throw new FileNotFoundException("footprint_lookup.mdb was not found.",s.FootprintLookupPath);if(q.LookupManufacturer.Trim().Length==0||q.LookupCatalog.Trim().Length==0)throw new InvalidOperationException("Manufacturer and catalog number are required to register the footprint lookup row.");if(q.LookupManufacturer.Length>24)throw new InvalidOperationException("MANUFACTURER is limited to 24 characters.");if(q.LookupCatalog.Length>60)throw new InvalidOperationException("CATALOG is limited to 60 characters.");Ace.ValidateTable(q.LookupManufacturer);}
  if(s.BackupFolder.Trim().Length==0)throw new InvalidOperationException("Backup folder is not set (LSELIBRARYSETTINGS).");
  if(q.AddCatalogRecord){if(q.Kind==LibraryKind.UserCircuit)throw new InvalidOperationException("User circuits do not get catalog records.");if(q.PartNumber is null||q.CatalogRecord is null)throw new InvalidOperationException("Fill in the catalog record (Catalog record... button) or untick the catalog option.");CatalogTransactionService.Validate(s,NamingWorkbookService.Load(s),q.PartNumber,q.CatalogRecord);}
 }
 public static bool SameFolder(string a,string b){try{return Path.GetFullPath(a).TrimEnd('\\','/').Equals(Path.GetFullPath(b).TrimEnd('\\','/'),StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 public static string? FindByName(string root,string fileName,LibraryStandard std){try{foreach(string f in EnumerateDrawings(root,std))if(Path.GetFileName(f).Equals(fileName,StringComparison.OrdinalIgnoreCase))return f;}catch{}return null;}
 public static IEnumerable<string> EnumerateDrawings(string root,LibraryStandard std){if(!Directory.Exists(root))yield break;var stack=new Stack<string>();stack.Push(root);while(stack.Count>0){string d=stack.Pop();IEnumerable<string> files;try{files=Directory.EnumerateFiles(d,"*.dwg");}catch{continue;}foreach(string f in files)yield return f;IEnumerable<string> dirs;try{dirs=Directory.EnumerateDirectories(d);}catch{continue;}foreach(string sub in dirs)if(!NamingService.IsIgnoredFolder(Path.GetFileName(sub),std))stack.Push(sub);}}
}
public sealed class LibraryLock:IDisposable{
 FileStream? f; public static string PathFor(string folder)=>Path.Combine(folder,"LSE_Library.lock");
 public static LibraryLock Acquire(string folder,List<string> log){string p=PathFor(folder);var x=new LibraryLock();for(int i=0;i<40;i++){try{x.f=new FileStream(p,FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None,4096,FileOptions.DeleteOnClose);byte[] b=System.Text.Encoding.UTF8.GetBytes($"{Environment.UserName}@{Environment.MachineName} {DateTime.Now:s}");x.f.Write(b,0,b.Length);x.f.Flush();log.Add("Library lock: PASS");return x;}catch(IOException){Thread.Sleep(250);}}throw new InvalidOperationException("Another workstation is changing the icon menus right now (lock file "+p+"). Try again in a moment.");}
 public void Dispose(){try{f?.Dispose();}catch{}f=null;}
}
